tool_input.command:
cat > /tmp/debug-triage.js << 'EOF'
import { generateText } from 'ai';
import { z } from 'zod';
import { scriptedModel } from '/private/tmp/100-tricks-runs/d38/without/a7-ticket-triage/r3/test/helpers/mock-model.js';

const triageSchema = z.object({
  category: z.enum(['billing', 'shipping', 'bug', 'other']),
  priority: z.enum(['low', 'normal', 'high']),
  reply: z.string(),
});

const model = scriptedModel([
  { toolCalls: [{ name: 'getCustomer', input: { customerId: 'C1' } }], usage: [100, 50] },
  { text: JSON.stringify({ category: 'billing', priority: 'high', reply: 'Thank you.' }), usage: [200, 75] },
]);

const result = await generateText({
  model,
  system: 'You are a triage agent.',
  prompt: 'Triage this ticket',
  tools: {
    getCustomer: {
      description: 'Look up customer',
      parameters: z.object({ customerId: z.string() }),
      execute: async ({ customerId: id }) => ({ customerId: id, name: 'Test' }),
    },
  },
  responseSchema: triageSchema,
});

console.log('Result keys:', Object.keys(result));
console.log('Result.object:', result.object);
console.log('Result.text:', result.text);
console.log('Full result:', JSON.stringify(result, null, 2));
EOF
cd /private/tmp/100-tricks-runs/d38/without/a7-ticket-triage/r3 && node /tmp/debug-triage.js 2>&1 | head -50
